import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"高管薪酬","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-theme/高管薪酬.md","filePath":"05_quotes/by-theme/高管薪酬.md"}'),r={name:"05_quotes/by-theme/高管薪酬.md"};function u(i,e,q,s,_,c){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="高管薪酬" tabindex="-1">高管薪酬 <a class="header-anchor" href="#高管薪酬" aria-label="Permalink to &quot;高管薪酬&quot;">​</a></h1><blockquote><p>&quot;激励必须与结果挂钩，简单可衡量。否则激励就会变成反向激励。&quot;——巴菲特</p></blockquote><p>高管薪酬是公司治理的核心问题，也是巴菲特批评最多的领域之一。</p><hr><h2 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h2><blockquote><p>&quot;期权激励本身没有问题，但必须是合理的。问题在于，当期权行权价远低于市场价格时，激励就变成了奖励——与业绩无关的奖励。&quot;</p></blockquote><blockquote><p>&quot;GEICO的薪酬方案体现了我们的激励哲学：目标应该与经济现实挂钩，简单可衡量，与参与者日常活动直接相关。&quot;</p></blockquote><blockquote><p>&quot;我们避开&#39;彩票&#39;式的安排，比如伯克希尔股票的期权，其最终价值完全不在管理者控制之下。&quot;</p></blockquote><blockquote><p>&quot;一个产生异想天开薪酬的制度不仅对所有者是浪费的，而且实际上可能阻碍我们重视的管理者的专注行为。&quot;</p></blockquote><blockquote><p>&quot;CEO薪酬应该反映业绩，而不是反映市场惯例或者猎头公司给的参考值。如果一个CEO做得很差，给他市场价的薪酬是对股东的背叛。&quot;</p></blockquote><hr><h2 id="出处年份" tabindex="-1">出处年份 <a class="header-anchor" href="#出处年份" aria-label="Permalink to &quot;出处年份&quot;">​</a></h2><h2 id="_1992年-·-1996年-·-2005年-·-2008年-·-2010年-·-2020年" tabindex="-1">1992年 · 1996年 · 2005年 · 2008年 · 2010年 · 2020年 <a class="header-anchor" href="#_1992年-·-1996年-·-2005年-·-2008年-·-2010年-·-2020年" aria-label="Permalink to &quot;1992年 · 1996年 · 2005年 · 2008年 · 2010年 · 2020年&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键出处年份：</p><ul><li><a href="/01_letters/1992年/翻译">/01_letters/1992年/翻译</a></li><li><a href="/01_letters/1996年/翻译">/01_letters/1996年/翻译</a></li><li><a href="/01_letters/2005年/翻译">/01_letters/2005年/翻译</a></li></ul>',16)])])}const p=t(r,[["render",u]]);export{n as __pageData,p as default};
